import{_ as o,I as e,o as l,c as h,j as t,a as r,J as i,w as s,a4 as f}from"./chunks/framework.Co6Rcm-5.js";const w=JSON.parse('{"title":"AI Infra 体系总览","description":"从 Scaling Law 到计算、通信、训练、推理、数据与应用的大模型系统地图。","frontmatter":{"title":"AI Infra 体系总览","description":"从 Scaling Law 到计算、通信、训练、推理、数据与应用的大模型系统地图。"},"headers":[],"relativePath":"ai-infra/index.md","filePath":"ai-infra/index.md","lastUpdated":1786522313000}'),m={name:"ai-infra/index.md"};function c(b,a,g,u,p,k){const n=e("SummaryHero"),d=e("InteractiveFlow");return l(),h("div",null,[a[1]||(a[1]=t("h1",{id:"ai-infra-体系总览",tabindex:"-1"},[r("AI Infra 体系总览 "),t("a",{class:"header-anchor",href:"#ai-infra-体系总览","aria-label":"Permalink to “AI Infra 体系总览”"},"​")],-1)),a[2]||(a[2]=t("p",null,"AI Infra 的主线不是“堆更多 GPU”，而是让模型、数据、计算、通信、存储和服务系统在同一个约束下协同。Scaling Law 决定资源投入方向，分布式系统决定训练上限，推理系统决定规模化成本，数据与应用则决定这些能力是否真正产生价值。",-1)),i(n,{goals:["建立端到端系统地图","识别各层核心瓶颈","找到深入阅读入口"],duration:"约 20 分钟",output:"一张 AI Infra 学习路线"},{default:s(()=>[...a[0]||(a[0]=[t("p",null,"本页把 Notion 中“00—07”八个模块压缩为四层视图，并把新增的 CUDA / Triton 算子经验接到推理与训练链路中。",-1)])]),_:1}),a[3]||(a[3]=t("h2",{id:"一条完整链路",tabindex:"-1"},[r("一条完整链路 "),t("a",{class:"header-anchor",href:"#一条完整链路","aria-label":"Permalink to “一条完整链路”"},"​")],-1)),i(d,{preset:"infra"}),a[4]||(a[4]=f('<h2 id="四个核心判断" tabindex="-1">四个核心判断 <a class="header-anchor" href="#四个核心判断" aria-label="Permalink to “四个核心判断”">​</a></h2><ol><li><strong>资源扩展必须服从有效缩放。</strong> Kaplan 规律强调模型规模，Chinchilla 进一步指出模型参数与训练数据需要更均衡地扩展；只增加参数并不等于获得最佳性能。</li><li><strong>大规模训练首先是系统问题。</strong> SPTD、上下文并行、专家并行和 ZeRO 解决的是显存、通信与负载切分，而不是改变模型目标函数。</li><li><strong>推理优化必须同时看延迟、吞吐和显存。</strong> KV Cache、PagedAttention、Continuous Batching、量化与模型压缩分别作用在不同瓶颈上，没有单一技术能覆盖所有工作负载。</li><li><strong>算子优化从瓶颈判断开始。</strong> 在写 CUDA 或 Triton kernel 之前，先确定是 memory-bound、compute-bound 还是 launch-bound，再决定融合、分块或专用实现是否值得。</li></ol><h2 id="模块地图" tabindex="-1">模块地图 <a class="header-anchor" href="#模块地图" aria-label="Permalink to “模块地图”">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th><th>代表主题</th><th>深入阅读</th></tr></thead><tbody><tr><td>资源层</td><td>算力如何稳定组成集群</td><td>GPU/NPU、RDMA、集合通信、分布式存储</td><td><a href="/knowledge-summary/ai-infra/compute-network">计算、通信与云原生</a></td></tr><tr><td>执行层</td><td>模型怎样高效训练与服务</td><td>SPTD、ZeRO、Flash Attention、KV Cache</td><td><a href="/knowledge-summary/ai-infra/training-inference">训练与推理系统</a></td></tr><tr><td>模型层</td><td>训练什么、用什么数据</td><td>Transformer、MoE、Mamba、多模态、数据工程</td><td><a href="/knowledge-summary/ai-infra/models-data-apps">模型、数据与应用</a></td></tr><tr><td>内核层</td><td>单个热点路径怎样逼近硬件上限</td><td>Profiling、HBM、Fusion、Triton</td><td><a href="/knowledge-summary/ai-infra/operator-engineering">算子工程方法</a></td></tr></tbody></table><h2 id="深入专题" tabindex="-1">深入专题 <a class="header-anchor" href="#深入专题" aria-label="Permalink to “深入专题”">​</a></h2><p>这次扩展把原有四篇总览拆成十二篇可独立查阅的工程专题。总览负责建立边界，专题负责回答“怎样估算、怎样选择、怎样验证”。每篇都包含一手资料链接、工程限制和交互模型；Widget 中的数字是帮助形成量级直觉的估算，不替代真实集群压测。</p><h3 id="规模、硬件与通信" tabindex="-1">规模、硬件与通信 <a class="header-anchor" href="#规模、硬件与通信" aria-label="Permalink to “规模、硬件与通信”">​</a></h3><table tabindex="0"><thead><tr><th>专题</th><th>核心问题</th><th>交互入口</th></tr></thead><tbody><tr><td><a href="/knowledge-summary/ai-infra/scaling-workloads">Scaling 与工作负载建模</a></td><td>参数、token、算力和训练工期怎样形成闭环</td><td>训练计算量估算、工作负载决策卡</td></tr><tr><td><a href="/knowledge-summary/ai-infra/accelerators-memory">加速器与显存体系</a></td><td>算力、HBM、精度与 Roofline 怎样共同决定上限</td><td>Roofline 实验室、精度策略权衡</td></tr><tr><td><a href="/knowledge-summary/ai-infra/interconnect-collectives">互连与集合通信</a></td><td>PCIe、NVLink、RDMA 与 collective 怎样映射</td><td>集合通信拓扑观察、互连方案选择</td></tr><tr><td><a href="/knowledge-summary/ai-infra/storage-checkpoint">存储与 Checkpoint</a></td><td>数据吞吐、状态一致性与恢复目标怎样权衡</td><td>Checkpoint 预算、存储路径选择</td></tr></tbody></table><h3 id="平台、训练与可靠性" tabindex="-1">平台、训练与可靠性 <a class="header-anchor" href="#平台、训练与可靠性" aria-label="Permalink to “平台、训练与可靠性”">​</a></h3><table tabindex="0"><thead><tr><th>专题</th><th>核心问题</th><th>交互入口</th></tr></thead><tbody><tr><td><a href="/knowledge-summary/ai-infra/scheduling-platform">调度与平台工程</a></td><td>Gang、配额、拓扑和多租户边界怎样协同</td><td>调度策略、多租户隔离决策</td></tr><tr><td><a href="/knowledge-summary/ai-infra/reliability-observability">可靠性与可观测性</a></td><td>如何从首个故障信号恢复到一致状态</td><td>恢复预算、可靠性控制面</td></tr><tr><td><a href="/knowledge-summary/ai-infra/distributed-training">分布式训练</a></td><td>DP、TP、PP、CP、EP 如何组合和放置</td><td>并行维度拓扑、策略组合卡</td></tr><tr><td><a href="/knowledge-summary/ai-infra/training-memory-numerics">训练显存与数值</a></td><td>模型状态、激活、重计算和低精度如何记账</td><td>训练显存账本、精度策略权衡</td></tr></tbody></table><h3 id="推理、数据与算子" tabindex="-1">推理、数据与算子 <a class="header-anchor" href="#推理、数据与算子" aria-label="Permalink to “推理、数据与算子”">​</a></h3><table tabindex="0"><thead><tr><th>专题</th><th>核心问题</th><th>交互入口</th></tr></thead><tbody><tr><td><a href="/knowledge-summary/ai-infra/inference-serving">推理服务系统</a></td><td>Prefill、Decode、KV Cache 和批处理如何协同</td><td>推理显存预算、调度策略卡</td></tr><tr><td><a href="/knowledge-summary/ai-infra/capacity-economics">容量规划与成本</a></td><td>如何从长度分布与 SLO 推导容量和单位经济性</td><td>在线容量估算、成本路径权衡</td></tr><tr><td><a href="/knowledge-summary/ai-infra/data-pipeline">数据流水线</a></td><td>来源、质量、版本和供数吞吐怎样被治理</td><td>数据吞吐预算、流水线决策卡</td></tr><tr><td><a href="/knowledge-summary/ai-infra/operator-compiler">算子与编译器</a></td><td>如何从性能指纹走到融合、分块和编译</td><td>Roofline 实验室、算子优化路径</td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to “学习顺序”">​</a></h2><ol><li>从 <a href="/knowledge-summary/ai-infra/scaling-workloads">Scaling 与工作负载建模</a> 建立计算量、数据量与工期的共同口径。</li><li>依次阅读 <a href="/knowledge-summary/ai-infra/accelerators-memory">加速器与显存体系</a> 和 <a href="/knowledge-summary/ai-infra/interconnect-collectives">互连与集合通信</a>，理解单卡与集群扩展的物理边界。</li><li>用 <a href="/knowledge-summary/ai-infra/distributed-training">分布式训练</a> 把并行维度映射到拓扑，再用 <a href="/knowledge-summary/ai-infra/training-memory-numerics">训练显存与数值</a> 校验容量与稳定性。</li><li>进入 <a href="/knowledge-summary/ai-infra/inference-serving">推理服务系统</a> 和 <a href="/knowledge-summary/ai-infra/capacity-economics">容量规划与成本</a>，把系统指标转换为用户 SLO 与成本。</li><li>最后以 <a href="/knowledge-summary/ai-infra/reliability-observability">可靠性与可观测性</a>、<a href="/knowledge-summary/ai-infra/data-pipeline">数据流水线</a> 和 <a href="/knowledge-summary/ai-infra/operator-compiler">算子与编译器</a> 补齐生产闭环。</li></ol><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/33b3a54bd6b481c78d98eeba043ef51e" target="_blank" rel="noreferrer">Notion：00 大模型系统概述</a></li><li><a href="https://app.notion.com/p/AIInfra-33b3a54bd6b4816bb189e32d4f1ee54e" target="_blank" rel="noreferrer">Notion：AIInfra 文档总结索引</a></li><li>原始课程：<a href="https://infrasys-ai.github.io/aiinfra-docs/" target="_blank" rel="noreferrer">AI Infra 文档</a></li></ul>',16))])}const P=o(m,[["render",c]]);export{w as __pageData,P as default};
